// Corrected stock measurements. f1's open trace ran after the creative dial
// had left the body on "Please rotate the creative dial", so Up never reached
// the direct screen. This run does not move that dial or the still/movie switch
// before the open. It traces Up and MENU, opens C1's size editor, and shows a
// custom zone on the stock direct screen. No overlay. No behaviour hook.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/stock_gaps_f2.mjs om-emu
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/stock_gaps_f2.mjs om-emu\n');
  process.exit(2);
}
process.env.OM_EMU_MODEL = 'E147';
const use = (p) => import(pathToFileURL(resolve(checkout, 'emu', p)).href);
const OUT = resolve('work/out/stock-gaps-f2.jsonl');
const GETTER = 0x60063380;
const SETTER = 0x60063431;
const CALL_CAP = 20000;

const { loadNand, loadImage, loadBlock, createHash: fwHash } = await use('checks/lib/env.mjs');
const { IMAGE_BASE } = await use('src/fw/model.mjs');
const { Player } = await use('src/lab/player.mjs');
const { apply_uiin_layout } = await use('src/lab/play.mjs');
const { PLAYER_PARSER } = await use('scenarios/session_replay.mjs');
const { MenuWalk } = await use('src/lab/menuwalk.mjs');
const { write_png } = await use('checks/lib/png.mjs');
const { words_to_rgb } = await use('src/lab/display.mjs');
const { fileNvram } = await use('host/nvram.mjs');
const { setExecTrace } = await use('src/core/cpu.mjs');
const { setForceHelper } = await use('src/core/interp.mjs');

const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify({
    step: row.step, screen: row.screen, zone: row.zone, calls: row.callCount,
    capped: row.callCapped, custom: row.customTouched, sets: (row.sets || []).length, diff: row.diff,
  }));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const hex = (v) => '0x' + (v >>> 0).toString(16);
const native = (address) => (0x50000000 + address - IMAGE_BASE) >>> 0;
const fw = { rom: loadImage(), resBlock: loadBlock(), summary: null, changed: [] };
apply_uiin_layout(fw.rom);
const nv = fileNvram(resolve('work/out/nvram-stock-gaps-f2.json'));
const pl = new Player(
  { ...PLAYER_PARSER, no_browser: true, idle: 'off', a15: 'on', out: '<out>', no_wait_on_error: true },
  {
    ...fw, nand: loadNand(), createHash: fwHash, wallClock: () => performance.now() / 1000,
    machine: { coverage: { mark() {}, stub() {} } }, nvram: nv, patch: null, patchRanges: [], loaded: 'on',
  },
);
pl.camapp_components = true;
pl.camapp_native_tra = true;

function diffCells(a, b, path = '', out = []) {
  if (Array.isArray(a) && Array.isArray(b)) {
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) out.push([path + '[' + i + ']', a[i], b[i]]);
    return out;
  }
  if (a && b && typeof a === 'object') {
    for (const k of Object.keys(a)) diffCells(a[k], b[k], path ? path + '.' + k : k, out);
    return out;
  }
  if (a !== b) out.push([path, a, b]);
  return out;
}
function titleHash(frame) {
  const [w, h, words] = frame;
  const y1 = Math.max(1, Math.min(h, Math.floor(h * 0.16)));
  const x0 = Math.floor(w * 0.22);
  const x1 = Math.floor(w * 0.78);
  const buf = Buffer.alloc((x1 - x0) * y1 * 4);
  let o = 0;
  for (let y = 0; y < y1; y++) for (let x = x0; x < x1; x++) { buf.writeUInt32LE(words[y * w + x] >>> 0, o); o += 4; }
  return { w, h, x0, x1, y1, sha256: createHash('sha256').update(buf).digest('hex') };
}

let failed = null;
try {
  pl.open_session();
  const s = pl.session;
  const l = s.lab;
  const gate = { reading: false, on: false };
  const sets = [];
  let tracing = false;
  let lastPc = 0;
  let lastOp = 0;
  let callEvents = 0;
  let callCapped = false;
  const callEntries = [];
  const seenCalls = new Set();
  l.observe(native(SETTER), (_lab, r) => {
    if (!gate.on || gate.reading || sets.length >= 60) return;
    const key = r.d0 & 0xffff;
    sets.push({ key: hex(key), index: r.d1 & 0xffff, a1: hex(r.a1 >>> 0), caller: hex(r.mdr >>> 0) });
  }, 'obs-setter-f2');
  setExecTrace((pc, op) => {
    if (!tracing) return;
    const p = pc >>> 0;
    const delta = (p - lastPc) >>> 0;
    if (lastPc && (delta > 6 || p < lastPc)) {
      let call = lastOp === 0xdd || lastOp === 0xcd;
      if (!call && (lastOp === 0xfc || lastOp === 0xfa)) {
        try { call = l.sim.read(lastPc, 2)[1] === 0xff; } catch { /* unreadable */ }
      }
      if (call) {
        callEvents += 1;
        if (!seenCalls.has(p)) {
          if (callEntries.length >= CALL_CAP) callCapped = true;
          else { seenCalls.add(p); callEntries.push(hex(p)); }
        }
      }
    }
    lastPc = p;
    lastOp = op & 0xff;
  });
  const callSaved = (fn) => {
    const saved = l.sim.registers();
    const was = tracing;
    tracing = false;
    gate.reading = true;
    try { return fn(); }
    finally { gate.reading = false; tracing = was; l.sim.reset(saved); }
  };
  const readKey = (key, index) => callSaved(() => l.call(native(GETTER), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff);
  const writeKey = (key, index, value) => callSaved(() => l.call(native(SETTER), { d0: key, d1: index, a1: value }, null, null, 200000));
  const arr = (key, n) => Array.from({ length: n }, (_, i) => readKey(key, i));
  const cells = () => ({
    k99a1: arr(0x99a1, 8),
    k9a41: arr(0x9a41, 2),
    k5962: arr(0x5962, 6),
    k1dd1: arr(0x1dd1, 10),
    k1de1: arr(0x1de1, 8),
    k84d1: readKey(0x84d1, 0),
    k5a11: arr(0x5a11, 11),
    k9fa1: arr(0x9fa1, 3),
    k90a1: [readKey(0x90a1, 0), readKey(0x90a1, 1)],
    ke91: readKey(0xe91, 3),
  });
  const idle = (ms) => { const to = l.lab_time() + ms * 1e6; while (l.lab_time() < to) s.idle_slice(Math.min(to, l.lab_time() + 50e6)); };
  const key = (k, d) => { s.key(k, d); s.camapp.pump(); };
  const press = (k) => { key(k, 'down'); idle(80); key(k, 'up'); idle(400); };
  const dial = (which, n) => { s.dial_input(which, n); s.camapp.pump(); idle(400); };
  const walk = new MenuWalk({ press, frame: () => s.frame('boundary'), draws: () => l.draw_log }, { limit: 8 });
  let shotN = 0;
  let before = null;
  const clearCalls = () => {
    callEntries.length = 0; seenCalls.clear(); callEvents = 0; callCapped = false; lastPc = 0; lastOp = 0; sets.length = 0;
  };
  const snap = (step, keepCalls) => {
    let texts = [];
    let frame = null;
    let textError = null;
    try {
      const scr = walk.read();
      texts = scr.texts.map((t) => t.text);
      frame = scr.frame;
    } catch (e) {
      textError = String(e && e.message || e);
      frame = s.frame('boundary');
    }
    if (!frame) throw new Error('screenshot failed at ' + step + ': ' + textError);
    const file = resolve('work/out/stock-gaps-f2-' + String(shotN).padStart(2, '0') + '-' + step + '.png');
    shotN += 1;
    write_png(file, frame[0], frame[1], words_to_rgb(frame[2]));
    const now = cells();
    const diff = before ? diffCells(before, now) : [];
    let stateName = null;
    try { stateName = l.state_names.get(l.state()) ?? null; } catch { /* unread */ }
    const row = {
      hook: 'observe', role: 'observe', step,
      screen: s.screen(), stateName, texts, textError,
      screenshot: file.split(/[/\\]/).pop(),
      title: titleHash(frame),
      cells: now, diff, zone: now.k99a1[1],
      customTouched: diff.some((d) => /^k1dd1\[[2-9]\]$/.test(String(d[0]))),
      sets: sets.slice(),
      calls: keepCalls ? callEntries.slice() : undefined,
      callCount: callEntries.length, callEvents, callCapped, callCap: CALL_CAP,
    };
    emit(row);
    before = now;
    return row;
  };
  const act = (step, fn) => { clearCalls(); fn(); return snap(step, false); };
  const traced = (step, fn) => {
    clearCalls();
    tracing = true;
    setForceHelper(true);
    try { fn(); }
    finally { tracing = false; setForceHelper(false); }
    return snap(step, true);
  };
  const toShooting = () => {
    for (let i = 0; i < 6 && s.screen() !== 'shooting'; i++) act('to-shooting-' + i, () => press('menu'));
  };

  emit({
    hook: 'observe', role: 'observe', step: 'setup',
    note: 'Stock image. Creative dial and still/movie switch stay at idle until the direct-screen traces finish. Unique call cap 20000. f1 showed Right on C1 opens the size editor and OK writes 0x1dd1 index 2.',
    routesNotWired: [
      { id: 'ael', reason: '0x120b is only in UI_IN variant 1; the lab board 0 reads variant 0. f1 pressed it and the screen stayed shooting.' },
      { id: 'bkt', reason: 'the key matrix has no BKT key' },
      { id: 'lock', reason: 'the producer of 0x0202123d/0x0202123e is unknown' },
    ],
  });
  gate.on = true;
  idle(1000);
  snap('baseline', false);

  const opened = traced('open-up', () => press('up'));
  if (opened.screen !== 'direct') throw new Error('open-up stayed on ' + opened.screen);
  act('dial-single', () => dial('main', 1));
  const cancelled = traced('cancel-menu', () => press('menu'));
  toShooting();

  const prior = arr(0x5a11, 11);
  for (let i = 0; i < 11; i++) writeKey(0x5a11, i, 1);
  emit({
    hook: 'observe', role: 'observe', step: 'enable-custom-slots',
    note: 'Native setter 0x60063431 wrote 0x5a11[0..10] = 1 so the stock direct screen can offer C1. Not an overlay.',
    before: prior, after: arr(0x5a11, 11),
  });
  const reopened = act('custom-direct-open', () => press('up'));
  if (reopened.screen !== 'direct') throw new Error('custom open stayed on ' + reopened.screen);
  let customZone = null;
  for (let i = 0; i < 12 && s.screen() === 'direct'; i++) {
    const row = act('custom-direct-dial-' + i, () => dial('main', 1));
    if (row.zone >= 6 && row.zone <= 9) { customZone = row; break; }
  }
  if (!customZone) throw new Error('direct screen did not reach a custom zone');
  act('custom-direct-hold', () => {});
  toShooting();

  act('menu-open', () => press('menu'));
  for (let i = 0; i < 24; i++) {
    let pageTexts = [];
    try { pageTexts = walk.read().texts.map((t) => t.text); } catch { pageTexts = []; }
    if (pageTexts.some((t) => String(t).includes('AF Target Settings'))) break;
    act('tab-left-' + i, () => press('left'));
  }
  act('mode-settings-ok', () => press('ok'));
  for (let i = 0; i < 5; i++) act('mode-down-' + i, () => press('down'));
  const entered = traced('c1-right', () => press('right'));
  act('size-dial-v', () => dial('main', 1));
  act('size-dial-h', () => dial('sub', 1));
  const committed = traced('size-ok', () => press('ok'));
  emit({
    hook: 'observe', role: 'observe', step: 'size-editor-summary',
    openScreen: opened.screen, openCalls: opened.callCount, openCapped: opened.callCapped,
    cancelScreen: cancelled.screen, cancelCalls: cancelled.callCount, cancelCapped: cancelled.callCapped,
    c1RightScreen: entered.screen, c1RightCalls: entered.callCount, c1RightCapped: entered.callCapped,
    okCalls: committed.callCount, okCapped: committed.callCapped,
    okSets: committed.sets, okDiff: committed.diff,
    customZone: customZone.zone, customTitle: customZone.title,
    allTitle: opened.title, singleFromDial: true,
  });
  emit({ hook: 'observe', role: 'observe', step: 'done', ok: true });
} catch (e) {
  failed = String(e && e.stack ? e.stack : e);
  emit({ hook: 'observe', role: 'observe', step: 'done', ok: false, error: failed });
  process.exitCode = 1;
} finally {
  try { setExecTrace(null); setForceHelper(false); } catch { /* already clear */ }
  if (pl.session) pl.close_session();
  writeFileSync(OUT, lines.join('\n') + (lines.length ? '\n' : ''));
}
if (failed) process.exit(1);
